import{installCloudLabTheme}from"./chunk-Y2MXV4LJ.js";function selectedCloudDemo(url=window.location.href){const demo=new URL(url).searchParams.get("demo");return demo==="planet"?demo:"flat"}function cloudDemoUrl(demo,url=window.location.href){const target=new URL(url);target.searchParams.set("demo",demo==="planet"?demo:"flat");return target.href}function mountCloudDemoNavigation(doc=document,url=window.location.href){installCloudLabTheme(doc);if(doc.getElementById("cloud-demo-navigation"))return;const nav=doc.createElement("nav");nav.id="cloud-demo-navigation";nav.setAttribute("aria-label","Cloud demos");nav.className="cl-switch cl-switch--floating";const current=selectedCloudDemo(url);for(const[demo,label]of[["flat","Flat clouds"],["planet","Planet clouds"]]){const link=doc.createElement("a");link.textContent=label;link.href=cloudDemoUrl(demo,url);if(demo===current){link.setAttribute("aria-current","page");link.addEventListener("click",event=>event.preventDefault())}nav.appendChild(link)}doc.body.appendChild(nav)}export{selectedCloudDemo,cloudDemoUrl,mountCloudDemoNavigation};
